/**
 * open-dynamic-workflows orchestration script
 * topology: hybrid
 * prompt: audit a repo for missing input validation
 */

async function execute(context) {
  const results = {};
  // ─── Discover (discovery) ───
  phase("Discover", { estimatedAgents: 1 });
  results["discover"] = await agent({ role: "discovery-agent", prompt: "Enumerate the concrete targets for: audit a repo for missing input validation", schema: {"items":"array"}, maxTokens: 4000, timeout: 120 });
  await checkpoint({ phase: "discover", data: results["discover"] });

  // ─── Work (analysis) ───
  phase("Work", { estimatedAgents: undefined });
  {
    const items = (results["discover"] && results["discover"].items) || [];
    log('Work: fanning out over ' + items.length + ' items');
    const work_raw = await parallel(
      items.map((item) => () => agent({ role: "analysis-agent", prompt: "Analyze ONE target for: audit a repo for missing input validation Item: " + JSON.stringify(item), schema: {"findings":"array","confidence":"number"}, maxTokens: 4000, timeout: 120 }).catch((e) => ({ __odw_failed: true, error: String((e && e.message) || e) }))),
      { maxConcurrency: 4 }
    );
    const work_ok = work_raw.filter((r) => !(r && r.__odw_failed));
    const work_dropped = work_raw.length - work_ok.length;
    if (work_dropped > 0) log('Work: ' + work_dropped + '/' + work_raw.length + ' items failed and were dropped', 'warn');
    results["work"] = work_ok;
  }
  await checkpoint({ phase: "work", data: results["work"] });

  // ─── Verify (verification) ───
  phase("Verify", { estimatedAgents: 1 });
  results["verify"] = await verify({
    target: results["work"],
    mode: 'adversarial',
    critics: [
      { role: 'false-positive-hunter', prompt: 'Find false positives in these findings. Assume some are wrong.' },
      { role: 'severity-validator', prompt: 'Challenge the severity ratings of these findings.' },
      { role: 'completeness-checker', prompt: 'What is MISSING from these findings?' },
    ],
    consensusThreshold: 2,
    minConfidence: 0.8,
  });
  await checkpoint({ phase: "verify", data: results["verify"] });

  // ─── Synthesize (synthesis) ───
  phase("Synthesize", { estimatedAgents: 1 });
  try {
    results["synthesize"] = await agent({ role: "synthesis-agent", prompt: "Merge verified results into the final deliverable." + ' Context: ' + JSON.stringify({ verify: results["verify"] }).slice(0, 20000), schema: {"summary":"string","details":"array"}, maxTokens: 8000, timeout: 120 });
  } catch (e) {
    if (e && (e.code === 'aborted' || e.code === 'paused')) throw e;
    log('synthesis could not produce structured output (' + e.message + ') — returning partial results', 'warn');
    results["synthesize"] = { summary: 'Workflow completed with partial results; the final synthesis step could not be formatted by the model.', partial: results["verify"], synthesisError: String(e.message) };
  }
  await checkpoint({ phase: "synthesize", data: results["synthesize"] });

  return results["synthesize"];
}

module.exports = { execute };
